package io.github.jesterportfolio.hearth.economy;

import java.util.*;
import java.math.BigInteger;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

final class PeerTradeTest {
    final UUID a=new UUID(1,1),b=new UUID(1,2);PeerTrade deal(){return new PeerTrade(new UUID(2,1),new UUID(3,1),a,b);}
    PeerTrade ready(){var d=deal();d.accept(b);d.edit(a,new PeerTrade.Offer(Map.of("stone",2),10));return d;}
    @Test void invitationCannotBeAcceptedByInitiatorOrThirdParty(){var d=deal();assertThrows(IllegalStateException.class,()->d.accept(a));assertThrows(SecurityException.class,()->d.accept(UUID.randomUUID()));assertEquals(PeerTrade.State.INVITED,d.state());}
    @Test void bothMustApproveSameRevisionAndDuplicateApprovalDoesNotCommit(){var d=ready();assertFalse(d.confirm(a,d.revision()));assertFalse(d.confirm(a,d.revision()));assertTrue(d.confirm(b,d.revision()));assertEquals(PeerTrade.State.COMMITTING,d.state());assertThrows(IllegalStateException.class,()->d.confirm(a,d.revision()));}
    @Test void anyRealOfferChangeRevokesBothApprovalsAndStaleScreenCannotApprove(){var d=ready();long seen=d.revision();d.confirm(a,seen);d.edit(b,new PeerTrade.Offer(Map.of(),4));assertTrue(d.approvals().isEmpty());assertThrows(IllegalStateException.class,()->d.confirm(b,seen));assertFalse(d.confirm(b,d.revision()));}
    @Test void identicalOfferDoesNotInvalidateAlreadyReviewedRevision(){var d=ready();long n=d.revision();d.confirm(a,n);d.edit(a,d.offer(a));assertEquals(n,d.revision());assertEquals(Set.of(a),d.approvals());}
    @Test void emptyTradeAndEditsAfterCommitAreRejected(){var d=deal();d.accept(b);assertThrows(IllegalStateException.class,()->d.confirm(a,0));d.edit(a,new PeerTrade.Offer(Map.of(),1));d.confirm(a,1);d.confirm(b,1);assertThrows(IllegalStateException.class,()->d.edit(a,PeerTrade.Offer.empty()));}
    @Test void cancellationBeforeCommitHasNoPendingValueAndDuringCommitRequiresHold(){var d=ready();d.cancel(a);assertEquals(PeerTrade.State.CANCELLED,d.state());var x=ready();x.confirm(a,x.revision());x.confirm(b,x.revision());x.cancel(b);x.complete(true);assertEquals(PeerTrade.State.HOLD,x.state());}
    @Test void storageRequestCannotCombineRealmsSelfOrEmptyTrades(){var access=new io.github.jesterportfolio.hearth.persistence.ServerProgressAccess();var first=access.forVerifiedServerLink(new UUID(3,1),a);var second=access.forVerifiedServerLink(new UUID(3,2),b);var offered=new PeerTrade.Offer(Map.of("stone",1),0);assertThrows(io.github.jesterportfolio.hearth.persistence.StorageFailure.class,()->new EconomyStore.PeerRequest(UUID.randomUUID(),first,second,offered,PeerTrade.Offer.empty()));assertThrows(io.github.jesterportfolio.hearth.persistence.StorageFailure.class,()->new EconomyStore.PeerRequest(UUID.randomUUID(),first,first,offered,PeerTrade.Offer.empty()));var peer=access.forVerifiedServerLink(first.storyRunId(),b);assertThrows(io.github.jesterportfolio.hearth.persistence.StorageFailure.class,()->new EconomyStore.PeerRequest(UUID.randomUUID(),first,peer,PeerTrade.Offer.empty(),PeerTrade.Offer.empty()));}
    @Test void knownPrecommitRefusalClosesCancelledAttemptWithoutClaimingSuccess(){var d=ready();d.confirm(a,d.revision());d.confirm(b,d.revision());d.cancel(a);d.refused();assertEquals(PeerTrade.State.CANCELLED,d.state());assertTrue(d.approvals().isEmpty());}
    @Test void fingerprintIsStableAcrossMapOrderAndChangesWithOwnerOrOffer(){var d=deal();d.accept(b);d.edit(a,new PeerTrade.Offer(Map.of("wood",1,"stone",2),3));var x=deal();x.accept(b);var map=new LinkedHashMap<String,Integer>();map.put("stone",2);map.put("wood",1);x.edit(a,new PeerTrade.Offer(map,3));assertEquals(d.fingerprint(),x.fingerprint());x.edit(b,new PeerTrade.Offer(Map.of(),1));assertNotEquals(d.fingerprint(),x.fingerprint());}
    @Test void quantityMoneyAndIdentifierLimitsRejectInvalidOffers(){assertThrows(IllegalArgumentException.class,()->new PeerTrade.Offer(Map.of("stone",0),0));assertThrows(IllegalArgumentException.class,()->new PeerTrade.Offer(Map.of("stone",4097),0));assertThrows(IllegalArgumentException.class,()->new PeerTrade.Offer(Map.of("../stone",1),0));assertThrows(IllegalArgumentException.class,()->new PeerTrade.Offer(Map.of(),-1));}
    @Test void balancesConserveMoneyIncludingLongBoundaryAndRefuseFundsOrOverflow(){var one=new PeerTrade.Offer(Map.of(),17);var two=new PeerTrade.Offer(Map.of(),4);var result=PeerTrade.balances(20,10,one,two);assertEquals(new PeerTrade.Balances(7,23),result);var large=PeerTrade.balances(Long.MAX_VALUE,Long.MAX_VALUE,one,one);assertEquals(BigInteger.valueOf(Long.MAX_VALUE).multiply(BigInteger.TWO),BigInteger.valueOf(large.first()).add(BigInteger.valueOf(large.second())));assertThrows(IllegalArgumentException.class,()->PeerTrade.balances(1,10,one,two));assertThrows(IllegalArgumentException.class,()->PeerTrade.balances(Long.MAX_VALUE,10,PeerTrade.Offer.empty(),two));}
}
